import React from 'react';
import { isSettingsHandlerE2eTraceEnabled, pushSettingsHandlerE2eTrace } from '../lib/e2eSettingsHandlerTrace.js';

function readOfflineKillActiveFromE2eCap() {
    try {
        const cap = globalThis.__NEURAL_SHELL_E2E_SETTINGS_HANDLER_TRACE__;
        return Boolean(cap && cap.offlineKillActive === true);
    } catch {
        return false;
    }
}

const CommandPalette = React.lazy(() => import('./CommandPalette'));

const SettingsDrawer = React.lazy(() => {
    if (isSettingsHandlerE2eTraceEnabled()) {
        pushSettingsHandlerE2eTrace({
            kind: 'settings-drawer-suspense-child-requested',
            chunk: 'SettingsDrawer',
            component: 'PaletteAndSettingsLayer',
        });
        pushSettingsHandlerE2eTrace({
            kind: 'settings-drawer-lazy-import-start',
            chunk: 'SettingsDrawer',
            component: 'PaletteAndSettingsLayer',
        });
    }
    return import('./SettingsDrawer')
        .then((mod) => {
            if (isSettingsHandlerE2eTraceEnabled()) {
                pushSettingsHandlerE2eTrace({
                    kind: 'settings-drawer-lazy-import-resolved',
                    chunk: 'SettingsDrawer',
                    resolvedType: 'module',
                    hasDefault: Boolean(mod && mod.default),
                    component: 'PaletteAndSettingsLayer',
                });
            }
            return mod;
        })
        .catch((err) => {
            if (isSettingsHandlerE2eTraceEnabled()) {
                const msg = err && err.message ? String(err.message) : String(err);
                pushSettingsHandlerE2eTrace({
                    kind: 'settings-drawer-lazy-import-rejected',
                    chunk: 'SettingsDrawer',
                    message: msg.slice(0, 400),
                    name: err && err.name ? String(err.name).slice(0, 120) : 'Error',
                    stackPreview: err && err.stack ? String(err.stack).slice(0, 400) : '',
                    component: 'PaletteAndSettingsLayer',
                });
            }
            throw err;
        });
});

/** Renders nothing; when Suspense shows fallback this mounts so E2E can detect stuck chunk loads. */
function SettingsDrawerSuspenseFallback({ showSettings: showSettingsProp }) {
    React.useLayoutEffect(() => {
        if (!isSettingsHandlerE2eTraceEnabled()) return;
        pushSettingsHandlerE2eTrace({
            kind: 'settings-drawer-suspense-fallback-rendered',
            showSettings: Boolean(showSettingsProp),
            component: 'PaletteAndSettingsLayer',
        });
    }, [showSettingsProp]);
    return null;
}

/**
 * Command palette and settings drawer — always mounted conditionally with Suspense
 * so lazy chunks resolve cleanly.
 */
const PaletteAndSettingsLayer = React.memo(function PaletteAndSettingsLayer({
    showPalette,
    onClosePalette,
    showSettings,
}) {
    // Warm lazy chunks on shell mount so CI/Electron serial suites do not race
    // Suspense(null) + first-open on slow Windows runners.
    React.useEffect(() => {
        void import('./CommandPalette');
        void import('./SettingsDrawer');
    }, []);

    React.useEffect(() => {
        pushSettingsHandlerE2eTrace({ kind: 'palette-showSettings-prop', value: Boolean(showSettings) });
    }, [showSettings]);

    React.useLayoutEffect(() => {
        if (!isSettingsHandlerE2eTraceEnabled()) return;
        const offlineKillActive = readOfflineKillActiveFromE2eCap();
        pushSettingsHandlerE2eTrace({
            kind: 'settings-drawer-render-condition',
            shouldRender: Boolean(showSettings),
            showSettings: Boolean(showSettings),
            offlineKillActive,
            component: 'PaletteAndSettingsLayer',
        });
        if (showSettings) {
            pushSettingsHandlerE2eTrace({
                kind: 'settings-drawer-lazy-boundary-entered',
                showSettings: true,
                shouldRender: true,
                component: 'PaletteAndSettingsLayer',
            });
            pushSettingsHandlerE2eTrace({
                kind: 'settings-drawer-parent-before-child',
                showSettings: true,
                component: 'PaletteAndSettingsLayer',
            });
        }
    }, [showSettings]);

    React.useEffect(() => {
        if (!isSettingsHandlerE2eTraceEnabled() || !showSettings) return;
        pushSettingsHandlerE2eTrace({
            kind: 'settings-drawer-parent-after-child',
            showSettings: true,
            component: 'PaletteAndSettingsLayer',
        });
    }, [showSettings]);

    return (
        <>
            {showPalette && (
                <React.Suspense fallback={null}>
                    <CommandPalette onClose={onClosePalette} />
                </React.Suspense>
            )}
            {showSettings && (
                <React.Suspense fallback={<SettingsDrawerSuspenseFallback showSettings={showSettings} />}>
                    <SettingsDrawer />
                </React.Suspense>
            )}
        </>
    );
});

export default PaletteAndSettingsLayer;

